namespace PA.Tickets.Domain.Sla;
public sealed class BusinessCalendar
{
 private readonly IReadOnlyDictionary<DayOfWeek,(TimeSpan Start,TimeSpan End)> workingHours;private readonly IReadOnlySet<DateOnly> holidays;
 public string TimeZoneId{get;} public IReadOnlyDictionary<DayOfWeek,(TimeSpan Start,TimeSpan End)> WorkingHours=>workingHours;public IReadOnlySet<DateOnly> Holidays=>holidays;
 public BusinessCalendar(string timeZoneId,IReadOnlyDictionary<DayOfWeek,(TimeSpan Start,TimeSpan End)> workingHours,IReadOnlySet<DateOnly> holidays){TimeZoneId=timeZoneId;this.workingHours=workingHours;this.holidays=holidays;}
 public bool IsWorkingDay(DateOnly day)=>workingHours.ContainsKey(day.DayOfWeek)&&!holidays.Contains(day);public (TimeSpan Start,TimeSpan End) Hours(DayOfWeek day)=>workingHours[day];
 public DateTimeOffset AddWorkingMinutes(DateTimeOffset start,int minutes){if(minutes<0)throw new ArgumentOutOfRangeException(nameof(minutes));var zone=TimeZoneInfo.FindSystemTimeZoneById(TimeZoneId);var local=TimeZoneInfo.ConvertTime(start,zone).DateTime;var remaining=minutes;while(remaining>0){var date=DateOnly.FromDateTime(local);if(IsWorkingDay(date)){var h=Hours(local.DayOfWeek);var dayStart=date.ToDateTime(TimeOnly.FromTimeSpan(h.Start));var dayEnd=date.ToDateTime(TimeOnly.FromTimeSpan(h.End));if(local<dayStart)local=dayStart;if(local<dayEnd){var available=(int)Math.Floor((dayEnd-local).TotalMinutes);var use=Math.Min(remaining,available);local=local.AddMinutes(use);remaining-=use;if(remaining==0)break;}}local=date.AddDays(1).ToDateTime(TimeOnly.MinValue);}return new DateTimeOffset(local,zone.GetUtcOffset(local));}
 public int WorkingMinutesBetween(DateTimeOffset start,DateTimeOffset end){if(end<=start)return 0;var zone=TimeZoneInfo.FindSystemTimeZoneById(TimeZoneId);var local=TimeZoneInfo.ConvertTime(start,zone).DateTime;var finish=TimeZoneInfo.ConvertTime(end,zone).DateTime;var total=0;while(local<finish){var date=DateOnly.FromDateTime(local);if(IsWorkingDay(date)){var h=Hours(local.DayOfWeek);var from=local>date.ToDateTime(TimeOnly.FromTimeSpan(h.Start))?local:date.ToDateTime(TimeOnly.FromTimeSpan(h.Start));var to=finish<date.ToDateTime(TimeOnly.FromTimeSpan(h.End))?finish:date.ToDateTime(TimeOnly.FromTimeSpan(h.End));if(to>from)total+=(int)Math.Floor((to-from).TotalMinutes);}local=date.AddDays(1).ToDateTime(TimeOnly.MinValue);}return total;}
}
public enum SlaClockStatus{Running,Paused,Breached,Completed}
public sealed class SlaClock
{
 public SlaPolicyVersion Policy{get;}public SlaClockStatus Status{get;private set;}public DateTimeOffset StartedAt{get;}public DateTimeOffset? PausedAt{get;private set;}public DateTimeOffset? CompletedAt{get;private set;}public DateTimeOffset? ResponseDueAt{get;private set;}public DateTimeOffset? ResolutionDueAt{get;private set;}public int WaitingMinutes{get;private set;}public string? WaitingReason{get;private set;}
 public SlaClock(SlaPolicyVersion policy,BusinessCalendar calendar,DateTimeOffset startedAt){Policy=policy;StartedAt=startedAt;ResponseDueAt=policy.ResponseTargetMinutes is null?null:calendar.AddWorkingMinutes(startedAt,policy.ResponseTargetMinutes.Value);ResolutionDueAt=policy.ResolutionTargetMinutes is null?null:calendar.AddWorkingMinutes(startedAt,policy.ResolutionTargetMinutes.Value);Status=SlaClockStatus.Running;}
 public void Pause(string reason,DateTimeOffset at){if(Status!=SlaClockStatus.Running)throw new InvalidOperationException("Only running SLA clocks can pause.");if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("SLA pause reason is required.");Status=SlaClockStatus.Paused;PausedAt=at;WaitingReason=reason;}
 public void Resume(BusinessCalendar calendar,DateTimeOffset at){if(Status!=SlaClockStatus.Paused||PausedAt is null)throw new InvalidOperationException("Only paused SLA clocks can resume.");var pauseStartedAt=PausedAt.Value;var pausedMinutes=calendar.WorkingMinutesBetween(pauseStartedAt,at);WaitingMinutes+=pausedMinutes;if(ResponseDueAt is not null&&pauseStartedAt<=ResponseDueAt.Value)ResponseDueAt=calendar.AddWorkingMinutes(ResponseDueAt.Value,pausedMinutes);if(ResolutionDueAt is not null&&pauseStartedAt<=ResolutionDueAt.Value)ResolutionDueAt=calendar.AddWorkingMinutes(ResolutionDueAt.Value,pausedMinutes);PausedAt=null;WaitingReason=null;Status=SlaClockStatus.Running;}
 public bool CheckBreach(DateTimeOffset at){if(Status is SlaClockStatus.Completed or SlaClockStatus.Paused or SlaClockStatus.Breached)return false;var breached=(ResponseDueAt is not null&&at>=ResponseDueAt.Value)||(ResolutionDueAt is not null&&at>=ResolutionDueAt.Value);if(breached)Status=SlaClockStatus.Breached;return breached;}
 public void Complete(DateTimeOffset at){if(Status==SlaClockStatus.Completed)throw new InvalidOperationException("SLA clock is already complete.");CompletedAt=at;Status=SlaClockStatus.Completed;}
}
